pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: prioritize bins that leave the smallest post-residual.
    // Base score is already post_residual.

    // 2. Penalty for creating "wasteland": if we have a small gap that likely won't fit future items, penalize it.
    // If post_residual is small (e.g., < 10), it's either an excellent fit or a useless sliver.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0; 
    }

    // 3. Lookahead Matching: If the post_residual can accommodate the next item, reward this bin heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 4. Scarcity/Efficiency: If this is the only bin that fits the current item, prioritize it to avoid opening new bins.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // 5. Global state normalization: If the bin is a brand-new bin (residual == capacity), 
    // only use it if the mean_residual of existing bins is already very low (fragmented).
    if bin_residual == bin_capacity {
        if open_bins_count > 0 && mean_residual > 20.0 {
            // Existing bins are mostly empty, don't open a new one.
            score += 100.0;
        } else {
            // Existing bins are tight, opening a new one is acceptable.
            score += 10.0;
        }
    }

    // 6. Progression scaling: As we approach the end of the stream, prioritize closing bins (lower residuals).
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score: punish larger post-residuals (Best Fit logic)
    // We want to minimize post_residual, so it stays as the primary component.
    let mut score = post;

    // Penalty for creating "dead space" (residuals < 10 are often unusable for 10-100 range)
    // We apply a non-linear penalty for residuals that fall into the "fragmentation trap" (1-9)
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) * 5.0;
    }

    // Lookahead coupling: if the next item is large, penalize small residuals in this bin
    // that would force a new bin later.
    if next_item_size > 0 {
        let lookahead_penalty = if post < next_item_size as f64 {
            (next_item_size as f64 - post) * 0.5
        } else {
            0.0
        };
        score += lookahead_penalty;
    }

    // Stream progression adjustment:
    // As we approach the end of the stream, prioritize filling existing bins more aggressively 
    // to avoid leaving leftovers.
    let completion_factor = 1.0 - progress;
    score += (mean_residual - post) * completion_factor * 2.0;

    // New bin logic:
    // If the bin is empty (bin_residual == bin_capacity), it is a candidate for a new bin.
    // We heavily penalize opening a new bin unless the current fittings are highly inefficient.
    if bin_residual == bin_capacity {
        // Base cost to open a new bin is high. 
        // We only open if mean_residual is very high (meaning current bins are mostly empty).
        score = 80.0 + (mean_residual * 0.5);
    } else {
        // If it's the last fitting bin, slightly lower the score to encourage usage
        if fitting_bins_count == 1 {
            score -= 5.0;
        }
    }

    score
}

