    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // 1. Best-Fit Penalty: Penalize smaller post_residuals (tight fits) 
    // but only if they don't leave enough space for the next item.
    if !is_new_bin && next_item_size > 0 {
        if post_residual < next_item_size {
            // High penalty for creating 'stranded' space that won't fit the lookahead
            score += 45.0 + (next_item_size - post_residual) as f64;
        } else {
            // Reward fits that leave exactly enough space for the next item
            score -= 10.0 * (1.0 - (post_residual as f64 - next_item_size as f64) / 100.0);
        }
    }

    // 2. Global State Sensitivity: 
    // If we have many open bins, prioritize finishing them (lowering residuals).
    // If we are early in the stream, favor keeping bins open for larger future items.
    if !is_new_bin {
        score += (open_bins_count as f64 * 0.5) * (1.0 - progress);
    } else {
        // Penalize opening new bins, but reduce penalty as the stream progresses 
        // to avoid being stuck with inefficient bins at the end.
        score += 35.0 * (1.0 - progress);

        // If only one bin can fit the item, opening a new one is highly discouraged
        if fitting_bins_count > 0 {
            score += 50.0;
        }
    }

    // 3. Fragmentation Avoidance:
    // Penalize post_residuals that are small but not zero (unusable slivers)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 4. Mean Residual Balancing:
    // If current bin residual is way above the mean of other bins, 
    // prioritize it to normalize bin states.
    if !is_new_bin && (bin_residual as f64) > mean_residual {
        score -= 5.0;
    }

    score
}

