pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize small residuals (dead space) more heavily as the stream progresses
    // This forces tighter packing towards the end of the stream.
    let dead_space_penalty = (post * post) * (1.0 + progress);

    // Reward bins that can accommodate the next item (lookahead)
    // If next_item_size fits in the post_residual, reduce the score.
    let mut lookahead_bonus = 0.0;
    if next_item_size > 0 && post_residual >= next_item_size {
        lookahead_bonus = -400.0 * (1.0 - progress * 0.5);
    }

    // Penalize opening new bins unless the residual is very tight
    // If it's a new bin (bin_residual == bin_capacity), score based on capacity utilization
    let mut score = if bin_residual == bin_capacity {
        // Base cost for opening a new bin is high, but mitigated if we have many open bins
        150.0 + (100.0 - item_size as f64) * 2.0
    } else {
        dead_space_penalty + lookahead_bonus
    };

    // If this is the last fitting bin, reward taking it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 500.0;
    }

    // Adjust by mean residual to prevent fragmentation across bins
    score += (post - mean_residual).abs() * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: Heavily punish creating "dead space" that cannot fit typical small items (e.g., < 20).
    // If post_residual is small but > 0, it is often worse than a larger residual.
    if post_residual > 0 && post_residual < 20 {
        score += (20.0 - post_residual as f64) * 5.0;
    }

    // 2. Next-Item Lookahead: If the next item could fit into the current post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 1.5;
    }

    // 3. Bin Efficiency: Penalize opening new bins unless the current options are very poor.
    // Use the ratio of total items to progress to decide how aggressively to pack.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        // This is a new bin. Only pick it if existing bins are high-residual (bad fits).
        score += (mean_residual * 0.5) + (progress * 10.0);
    } else {
        // Existing bin: reward bins that are getting closer to capacity.
        score -= (bin_capacity - bin_residual) as f64 * 0.1;
    }

    // 4. Harmonic Alignment: Reward post_residuals that are multiples of common item sizes (e.g., 25, 33, 50).
    // This leaves the bin in a state where it can accept common item chunks later.
    let remainder = post_residual % 25;
    if remainder == 0 && post_residual > 0 {
        score -= 5.0;
    }

    // 5. Scarcity Constraint: If this is the only bin that fits the item, prioritize it strongly
    // to avoid the penalty of opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}
